// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address user, uint256 amount) internal {
        vm.assume(user != address(this) && user != address(c));
        uint256 balBefore = user.balance;
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted ? user.balance >= balBefore - amount : true);
    }

    function testFuzz_run(address user, uint256 amount) public {
        _run(user, amount);
    }

    receive() external payable {}
}
